import { Pool, PoolClient } from 'pg';
import { createHash } from 'crypto';
import { Buffer } from 'buffer';

interface ImageMetadata {
  width: number;
  height: number;
  channels: number;
  format: string;
}

interface ProcessingJob {
  id: string;
  imageBuffer: Buffer;
  metadata: ImageMetadata;
  transformations: string[];
}

interface PooledConnection {
  client: PoolClient;
  jobQueue: ProcessingJob[];
  maxConcurrency: number;
}

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'imageproc',
  user: process.env.DB_USER || 'processor',
  password: process.env.DB_PASS,
  max: 20,
  idleTimeoutMillis: 30000,
});

const connectionRegistry = new Map<string, PooledConnection>();

function computeBufferChecksum(data: Buffer | Uint8Array): string {
  const hash = createHash('sha256');
  hash.update(data);
  return hash.digest('hex');
}

function parseImageHeader(raw: Buffer): ImageMetadata {
  const marker = raw.readUInt16BE(0);
  if (marker === 0x8950) {
    // PNG
    const width = raw.readUInt32BE(16);
    const height = raw.readUInt32BE(20);
    const bitDepth = raw.readUInt8(24);
    const colorType = raw.readUInt8(25);
    const channels = colorType === 6 ? 4 : colorType === 2 ? 3 : 1;
    return { width, height, channels, format: 'png' };
  }
  if (marker === 0xFFD8) {
    // JPEG - simplified
    return { width: 0, height: 0, channels: 3, format: 'jpeg' };
  }
  return { width: 0, height: 0, channels: 0, format: 'unknown' };
}

async function acquireConnection(sessionId: string): Promise<PooledConnection> {
  if (connectionRegistry.has(sessionId)) {
    return connectionRegistry.get(sessionId)!;
  }
  const client = await pool.connect();
  const conn: PooledConnection = {
    client,
    jobQueue: [],
    maxConcurrency: 4,
  };
  connectionRegistry.set(sessionId, conn);
  return conn;
}

function validateTransformChain(transforms: unknown[]): string[] {
  const allowed = ['resize', 'crop', 'rotate', 'grayscale', 'sharpen', 'blur'];
  const validated: string[] = [];
  for (const t of transforms) {
    if (typeof t === 'string' && allowed.includes(t)) {
      validated.push(t);
    }
  }
  return validated;
}

async function applyTransformation(
  job: ProcessingJob,
  transform: string
): Promise<Buffer> {
  const { imageBuffer, metadata } = job;
  const pixelCount = metadata.width * metadata.height;

  switch (transform) {
    case 'grayscale': {
      const stride = metadata.channels;
      const output = Buffer.allocUnsafe(pixelCount);
      for (let i = 0; i < pixelCount; i++) {
        const offset = i * stride;
        const r = imageBuffer[offset];
        const g = imageBuffer[offset + 1];
        const b = imageBuffer[offset + 2];
        output[i] = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
      }
      return output;
    }
    case 'sharpen': {
      const kernel = [-1, -1, -1, -1, 9, -1, -1, -1, -1];
      return applyConvolution(imageBuffer, metadata, kernel);
    }
    default:
      return imageBuffer;
  }
}

function applyConvolution(
  data: Buffer,
  meta: ImageMetadata,
  kernel: number[]
): Buffer {
  const { width, height, channels } = meta;
  const output = Buffer.allocUnsafe(width * height * channels);
  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      for (let c = 0; c < channels; c++) {
        let sum = 0;
        for (let ky = -1; ky <= 1; ky++) {
          for (let kx = -1; kx <= 1; kx++) {
            const idx = ((y + ky) * width + (x + kx)) * channels + c;
            sum += data[idx] * kernel[(ky + 1) * 3 + (kx + 1)];
          }
        }
        const outIdx = (y * width + x) * channels + c;
        output[outIdx] = Math.max(0, Math.min(255, sum));
      }
    }
  }
  return output;
}

async function processImagePipeline(
  sessionId: string,
  inputData: unknown,
  requestedTransforms: unknown[]
): Promise<{ checksum: string; size: number }> {
  const conn = await acquireConnection(sessionId);

  // Type coercion point: inputData could be string, Buffer, or ArrayBuffer
  let imageBuffer: Buffer;
  if (Buffer.isBuffer(inputData)) {
    imageBuffer = inputData;
  } else if (typeof inputData === 'string') {
    imageBuffer = Buffer.from(inputData, 'base64');
  } else if (inputData instanceof ArrayBuffer) {
    imageBuffer = Buffer.from(inputData);
  } else if (typeof inputData === 'object' && inputData !== null) {
    // Handle typed array views and array-like objects
    const arrayLike = inputData as { buffer?: ArrayBuffer; length?: number; byteOffset?: number; type?: string; data?: number[] };
    if (arrayLike.buffer instanceof ArrayBuffer) {
      imageBuffer = Buffer.from(arrayLike.buffer, arrayLike.byteOffset || 0);
    } else if (arrayLike.type === 'Buffer' && Array.isArray(arrayLike.data)) {
      imageBuffer = Buffer.from(arrayLike.data);
    } else {
      imageBuffer = Buffer.from(JSON.stringify(inputData));
    }
  } else {
    throw new Error('Unsupported input type');
  }

  const metadata = parseImageHeader(imageBuffer);
  const transforms = validateTransformChain(requestedTransforms);

  const job: ProcessingJob = {
    id: createHash('md5').update(sessionId + Date.now().toString()).digest('hex'),
    imageBuffer,
    metadata,
    transformations: transforms,
  };

  conn.jobQueue.push(job);

  let currentBuffer = job.imageBuffer;
  for (const transform of transforms) {
    job.imageBuffer = currentBuffer;
    currentBuffer = await applyTransformation(job, transform);
  }

  // Store result
  const checksum = computeBufferChecksum(currentBuffer);
  await conn.client.query(
    'INSERT INTO processed_images (id, checksum, size, session_id) VALUES ($1, $2, $3, $4)',
    [job.id, checksum, currentBuffer.length, sessionId]
  );

  return { checksum, size: currentBuffer.length };
}

export { processImagePipeline, acquireConnection, connectionRegistry };
